def remove_Occ(s, char):
    # Find the first occurrence of the character
    first_occurrence = s.find(char)
    # Find the last occurrence of the character
    last_occurrence = s.rfind(char)
    # If character is found, remove it from the string
    if first_occurrence != -1 and last_occurrence != -1:
        if first_occurrence < last_occurrence:
            return s[:first_occurrence] + s[last_occurrence+1:]
        else:
            return s[:last_occurrence] + s[first_occurrence+1:]
    else:
        return s
