def is_woodall(n):
    # A number is a Woodall number if it can be expressed as k * 2^k - 1 for some integer k
    k = 1
    while True:
        woodall_num = k * (2 ** k) - 1
        if woodall_num == n:
            return True
        elif woodall_num > n:
            return False
        k += 1
