def check_triplet(arr, target_sum, a, b):
    arr.sort()
    n = len(arr)
    for i in range(n-2):
        left, right = i+1, n-1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target_sum:
                if arr[left] == a and arr[right] == b:
                    return True
                elif arr[left] == b and arr[right] == a:
                    return True
                left += 1
                right -= 1
            elif current_sum < target_sum:
                left += 1
            else:
                right -= 1
    return False
