def pancake_sort(arr):
    def flip(sub_arr, k):
        start = 0
        while start < k:
            sub_arr[start], sub_arr[k] = sub_arr[k], sub_arr[start]
            start += 1
            k -= 1

    n = len(arr)
    while n > 1:
        max_index = arr.index(max(arr[:n]))
        if max_index != n - 1:
            if max_index != 0:
                flip(arr, max_index + 1)
            flip(arr, n)
        n -= 1
    return arr
```

