def max_path_sum(triangle, row, col):
    # Base case: if we are at the last row, return the value at that position
    if row == len(triangle):
        return triangle[row][col]

    # If we are at the edge of the triangle, we can only move down or diagonally down-right
    if col == 0:
        return triangle[row][col] + max_path_sum(triangle, row + 1, col)
    elif col == len(triangle[row]) - 1:
        return triangle[row][col] + max_path_sum(triangle, row + 1, col - 1)
    else:
        # Otherwise, we can move down or diagonally down-right, and take the maximum of the two paths
        return triangle[row][col] + max(max_path_sum(triangle, row + 1, col), max_path_sum(triangle, row + 1, col - 1))
```

