def is_valid_parenthese(s):
    # Dictionary to map closing parentheses to their corresponding opening parentheses
    parentheses_map = {')': '(', '}': '{', ']': '['}
    # Stack to keep track of opening parentheses
    stack = []

    # Iterate through each character in the string
    for char in s:
        # If the character is an opening parenthesis, push it onto the stack
        if char in parentheses_map.values():
            stack.append(char)
        # If the character is a closing parenthesis
        elif char in parentheses_map:
            # If the stack is empty or the top of the stack doesn't match the corresponding opening parenthesis, return False
            if not stack or stack.pop() != parentheses_map[char]:
                return False
        # If the character is not a parenthesis, ignore it (or raise an error if you want to handle invalid input)
        else:
            continue

    # If the stack is empty, all parentheses were properly closed; otherwise, return False
    return not stack
```

