    # Place each number in its corresponding index (value at index i should be i+1)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            # Swap nums[i] with nums[nums[i] - 1]
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    # Find the first index where the value is not i+1
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    # If all positions are correct, the missing number is n+1
    return n + 1
