def max_sum(triangle, n):
    # Initialize a DP table with the same dimensions as the triangle
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Base case: the maximum sum for the single-element rows is the element itself
    for i in range(n):
        dp[i][i] = triangle[i][i]

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = max(dp[i][k] + dp[k + 1][j] for k in range(i, j))

    # The maximum sum is the maximum value in the last row of the DP table
    return max(dp[i][i] for i in range(n))
```

