def get_total_number_of_sequences(n, m):
    # Initialize a 2D list to store the number of sequences
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, j + 1):
                if k * 2 <= j:
                    dp[i][j] += dp[i - 1][k]

    # The result is the sum of all possible sequences of length n
    result = sum(dp[n])
    return result
