def max_sum(arr, n):
    # Initialize two arrays to store the maximum sum ending at each index
    # and the maximum sum starting at each index.
    max_sum_ending_here = [0] * n
    max_sum_starting_here = [0] * n

    max_sum_ending_here[0] = arr[0]
    max_sum_starting_here[0] = arr[0]

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and (i - j - 1) % 2 == 1:
                if max_sum_ending_here[j] + arr[i] > max_sum_ending_here[i]:
                    max_sum_ending_here[i] = max_sum_ending_here[j] + arr[i]
                    max_sum_starting_here[i] = max_sum_starting_here[j]
                elif max_sum_ending_here[j] + arr[i] == max_sum_ending_here[i]:
                    max_sum_starting_here[i] = max(max_sum_starting_here[i], max_sum_starting_here[j])
        if max_sum_ending_here[i] == 0:
            max_sum_ending_here[i] = arr[i]
        max_sum_starting_here[i] = max(max_sum_starting_here[i], arr[i])

    return max(max_sum_ending_here)

