    inv_count = 0
    if left < right:
        mid = (left + right) // 2
        inv_count += merge_sort(arr, left, mid)
        inv_count += merge_sort(arr, mid + 1, right)
        inv_count += merge(arr, left, mid, right)
    return inv_count

def merge(arr, left, mid, right):
    inv_count = 0
    i = left
    j = mid + 1
    k = left
    temp = []

    while i <= mid and j <= right:
        if arr[i] <= arr[j]:
            temp.append(arr[i])
            i += 1
        else:
            temp.append(arr[j])
            j += 1
            inv_count += (mid - i + 1)

    while i <= mid:
        temp.append(arr[i])
        i += 1

    while j <= right:
        temp.append(arr[j])
        j += 1

    for i in range(left, right + 1):
        arr[i] = temp[i - left]

    return inv_count
