def find_minimum_range(arrays):
    min_val = min(min(arr) for arr in arrays)
    max_val = max(max(arr) for arr in arrays)
    min_range = max_val - min_val

    start, end = min_val, max_val
    seen = [0] * len(arrays)

    while True:
        found = False
        for i in range(len(arrays)):
            if seen[i] == len(arrays[i]):
                continue
            if arrays[i][seen[i]] == min_val:
                seen[i] += 1
                found = True
                break
        if not found:
            break
        current_range = max_val - min_val
        if current_range < min_range:
            min_range = current_range
            start, end = min_val, max_val

    return (start, end)
```

