def permute_string(s):
    def permute(arr, l, r, temp):
        if l == r:
            temp.append(''.join(arr))
        else:
            for i in range(l, r + 1):
                arr[l], arr[i] = arr[i], arr[l]
                permute(arr, l + 1, r, temp)
                arr[l], arr[i] = arr[i], arr[l]  # backtrack

    n = len(s)
    temp = []
    permute(list(s), 0, n - 1, temp)
    return temp
