    while low < high:
        if arr[low] < arr[high]:
            return 0
        mid = (low + high) // 2
        next_mid = (mid + 1) % len(arr)
        prev_mid = (mid - 1 + len(arr)) % len(arr)
        if arr[mid] <= arr[next_mid] and arr[mid] <= arr[prev_mid]:
            return mid
        elif arr[mid] <= arr[high]:
            high = mid
        else:
            low = mid + 1
    return 0
