def ncr_modp(n, r, p):
    def mod_inv(x, p):
        for y in range(1, p):
            if (x * y) % p == 1:
                return y
        return None

    def mod_factorial(n, p):
        result = 1
        for i in range(2, n + 1):
            result = (result * i) % p
        return result

    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    r = min(r, n - r)  # Take advantage of symmetry
    numerator = mod_factorial(n, p)
    denominator = (mod_factorial(r, p) * mod_factorial(n - r, p)) % p
    return (numerator * pow(denominator, -1, p)) % p
```

