def rearrange_bigger(n):
    # Convert the number to a list of its digits
    digits = list(str(n))
    length = len(digits)

    # Traverse the list from the end to find the first digit that is smaller than the digit next to it
    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            # Find the smallest digit on the right side of the found digit which is greater than the found digit
            for j in range(length - 1, i, -1):
                if digits[j] > digits[i]:
                    # Swap the found digit with the digit just greater than it
                    digits[i], digits[j] = digits[j], digits[i]
                    # Sort the remaining digits to the right of the position i in ascending order
                    digits[i + 1:] = sorted(digits[i + 1:])
                    # Convert the list of digits back to an integer and return
                    return int(''.join(digits))
    # If no such arrangement is possible, return False
    return False
```

